/// Whether an error is a lost connection: a failure of the transport, a failure
/// of the body or a stall past the idle timeout.
fn is_connection_failure(failure: &(dyn std::error::Error + Send + Sync + 'static)) -> bool {
    failure.is::<NetworkError>()
        || failure.is::<StreamError>()
        || failure.is::<NetworkTimeoutError>()
}

/// Whether an error is a status a reconnect may get over: 408, 429 or 5xx.
fn is_retryable_status(failure: &(dyn std::error::Error + Send + Sync + 'static)) -> bool {
    match api_error_of(failure) {
        Some(api_error) => {
            let status = api_error.status_code();
            status == 408 || status == 429 || (500..=599).contains(&status)
        }
        None => false,
    }
}

/// The `Retry-After` of a 429, 502, 503 or 504 failure, if it sent one.
fn retry_after_of(
    failure: Option<&(dyn std::error::Error + Send + Sync + 'static)>,
) -> Option<Duration> {
    let api_error = api_error_of(failure?)?;
    if !matches!(api_error.status_code(), 429 | 502 | 503 | 504) {
        return None;
    }
    let value = api_error
        .response_headers()?
        .iter()
        .find(|(name, _)| name.eq_ignore_ascii_case("retry-after"))
        .map(|(_, value)| value)?;
    crate::api::base_api::parse_retry_after(value)
}

/// A uniform random value in [0, 1).
fn jitter_sample() -> f64 {
    f64::from(uuid::Uuid::new_v4().as_u128() as u32) / (f64::from(u32::MAX) + 1.0)
}

/// How long to wait before reconnect number `attempt` (1 for the first): the
/// server's `retry` value, else `Retry-After`, else `base` doubling to 30 seconds,
/// reduced by up to 25% of jitter. `jitter_sample` is a uniform random value in
/// [0, 1).
pub(crate) fn reconnect_wait(
    attempt: u32,
    base: Duration,
    server_retry: Option<u64>,
    retry_after: Option<Duration>,
    jitter_sample: f64,
) -> Duration {
    if let Some(millis) = server_retry {
        return Duration::from_millis(millis);
    }
    if let Some(wait) = retry_after {
        return wait;
    }
    let doubled = base
        .saturating_mul(1u32 << attempt.saturating_sub(1).min(20))
        .min(MAX_RECONNECT_DELAY);
    doubled.mul_f64(1.0 - 0.25 * jitter_sample)
}

#[cfg(test)]
mod tests {
    use bytes::Bytes;

    use super::*;
    use crate::byte_stream::ByteStream;
    use crate::json_lines_stream::JsonLinesStream;

    #[derive(Clone)]
    enum Connection {
        Text(&'static str),
        NoContent,
        Other(u16, &'static str),
        Failure(fn() -> Failure),
    }

    fn lost() -> Failure {
        let cause = std::io::Error::new(std::io::ErrorKind::ConnectionReset, "reset");
        let api_error = ApiError::transport(
            TransportFailure::Network,
            "reset".to_string(),
            Arc::new(cause),
        );
        Box::new(StreamError::from(
            NetworkError::try_from(api_error).expect("a network error"),
        ))
    }

    fn missing() -> Failure {
        Box::new(ApiError::new(
            404,
            "missing".to_string(),
            None,
            Some("{}".to_string()),
        ))
    }

    /* Opens an event stream whose n-th connection (from 1) is the n-th entry; the
     * last entry repeats. The last event ids the stream sent are recorded. */
    fn script(connections: Vec<Connection>) -> (EventOpener, Arc<Mutex<Vec<String>>>) {
        let ids = Arc::new(Mutex::new(Vec::new()));
        let recorded = ids.clone();
        let opener: EventOpener = Box::new(move |last_event_id| {
            let index = {
                let mut seen = recorded.lock().expect("ids");
                seen.push(last_event_id);
                seen.len().min(connections.len()) - 1
            };
            let next = connections[index].clone();
            Box::pin(async move {
                let stream_headers = || {
                    HashMap::from([("content-type".to_string(), "text/event-stream".to_string())])
                };
                match next {
                    Connection::Text(text) => Ok(ApiStreamResponse::new(
                        200,
                        stream_headers(),
                        futures_util::stream::iter(vec![Ok(Bytes::from(text))]),
                    )),
                    Connection::NoContent => Ok(ApiStreamResponse::new(
                        204,
                        HashMap::new(),
                        futures_util::stream::iter(Vec::new()),
                    )),
                    Connection::Other(status, content_type) => Ok(ApiStreamResponse::new(
                        status,
                        HashMap::from([("content-type".to_string(), content_type.to_string())]),
                        futures_util::stream::iter(Vec::new()),
                    )),
                    Connection::Failure(make) => Err(make()),
                }
            })
        });
        (opener, ids)
    }

    fn fast() -> StreamOptions {
        StreamOptions::new().reconnect_delay(Duration::from_millis(1))
    }

    fn text_decoder() -> DataDecoder<String> {
        Box::new(|data| Ok(data.to_string()))
    }

    async fn sse(opener: EventOpener, options: StreamOptions) -> SseStream<String> {
        SseStream::open(
            opener,
            text_decoder(),
            None,
            Some(&options),
            false,
            false,
            "GET",
            "/events",
        )
        .await
        .expect("the first connection opens")
    }

    async fn data_of(mut stream: SseStream<String>) -> Result<Vec<String>, Failure> {
        let mut data = Vec::new();
        while let Some(event) = stream.next().await {
            data.push(event?.data);
        }
        Ok(data)
    }

    #[tokio::test]
    async fn test_bhv_streaming_005_a_line_or_event_longer_than_the_limit_raises_a_serialization_error_and_ends_the_stream(
    ) {
        let source = ByteStream::new(
            200,
            HashMap::new(),
            Box::pin(futures_util::stream::iter(vec![Ok(Bytes::from(format!(
                "ok\n{}\nlater\n",
                "x".repeat(50)
            )))])),
        );
        let mut lines = JsonLinesStream::new(
            source,
            Box::new(|line| Ok(line.to_string())),
            10,
            "GET",
            "/items",
        );
        assert_eq!("ok", lines.next().await.expect("item").expect("decoded"));
        let failure = lines
            .next()
            .await
            .expect("the failure")
            .expect_err("line 2 is too long");
        assert!(failure.is::<SerializationError>());
        assert!(lines.next().await.is_none());

        let (opener, _) = script(vec![Connection::Text(
            "data: yyyyyyyyyyyyyyyyyyyyyyyyyyyyyy\n\n",
        )]);
        let options = StreamOptions::new().max_event_bytes(10);
        let mut events = sse(opener, options).await;
        let failure = events
            .next()
            .await
            .expect("the failure")
            .expect_err("the event is too long");
        assert!(failure.is::<SerializationError>());
        assert!(events.next().await.is_none());
    }

    #[tokio::test]
    async fn test_bhv_sse_005_an_sse_data_payload_is_decoded_and_a_payload_that_does_not_decode_raises_a_serialization_error_and_ends_the_stream(
    ) {
        let (opener, _) = script(vec![Connection::Text(
            "data: 1\n\ndata: oops\n\ndata: 3\n\n",
        )]);
        let decoder: DataDecoder<i64> = Box::new(|data| {
            data.parse::<i64>()
                .map_err(|e| SerializationError::new("not a number".to_string(), Some(Box::new(e))))
        });
        let mut stream = SseStream::open(
            opener,
            decoder,
            None,
            Some(&fast()),
            false,
            false,
            "GET",
            "/events",
        )
        .await
        .expect("opens");
        assert_eq!(
            1,
            stream.next().await.expect("event").expect("decoded").data
        );
        let failure = stream
            .next()
            .await
            .expect("the failure")
            .expect_err("oops does not decode");
        assert!(failure.is::<SerializationError>());
        assert!(stream.next().await.is_none());
    }

    #[test]
    fn test_bhv_sse_008_an_sse_reconnect_waits_the_server_retry_value_else_the_reconnect_delay_doubling_to_a_cap(
    ) {
        let second = Duration::from_secs(1);
        assert_eq!(
            Duration::from_millis(250),
            reconnect_wait(3, second, Some(250), None, 0.0)
        );
        assert_eq!(
            Duration::from_millis(1000),
            reconnect_wait(1, second, None, None, 0.0)
        );
        assert_eq!(
            Duration::from_millis(2000),
            reconnect_wait(2, second, None, None, 0.0)
        );
        assert_eq!(
            Duration::from_millis(4000),
            reconnect_wait(3, second, None, None, 0.0)
        );
        assert_eq!(
            Duration::from_millis(30_000),
            reconnect_wait(10, second, None, None, 0.0)
        );
        assert_eq!(
            Duration::from_millis(750),
            reconnect_wait(1, second, None, None, 1.0),
            "jitter takes up to 25%"
        );
        assert_eq!(
            Duration::from_secs(5),
            reconnect_wait(1, second, None, Some(Duration::from_secs(5)), 0.0),
            "Retry-After replaces it"
        );
    }

    #[tokio::test]
    async fn test_bhv_sse_009_an_sse_get_stream_stops_after_five_failed_reconnects_by_default_and_raises_the_last_failure(
    ) {
        let (opener, ids) = script(vec![Connection::Text("")]);
        let failure = data_of(sse(opener, fast()).await)
            .await
            .expect_err("the feed never comes back");
        assert!(failure.is::<StreamError>());
        assert_eq!(
            6,
            ids.lock().expect("ids").len(),
            "one request and five reconnects"
        );
    }

    #[tokio::test]
    async fn test_bhv_sse_010_an_sse_reconnect_counter_resets_after_an_event_is_received() {
        let (opener, _) = script(vec![
            Connection::Text("data: a\n\n"),
            Connection::Text("data: b\n\n"),
            Connection::Text("data: c\n\n"),
            Connection::Text(""),
        ]);
        let mut stream = sse(opener, fast().max_reconnects(1)).await;
        let mut seen = Vec::new();
        let failure = loop {
            match stream.next().await.expect("an item or the failure") {
                Ok(event) => seen.push(event.data),
                Err(failure) => break failure,
            }
        };
        assert!(failure.is::<StreamError>());
        assert_eq!(
            vec!["a", "b", "c"],
            seen,
            "three events survived a limit of one reconnect"
        );
    }

    #[tokio::test]
    async fn test_bhv_sse_011_an_sse_stream_does_not_reconnect_after_a_204_a_4xx_status_or_a_response_that_is_not_an_event_stream(
    ) {
        let (none, ids) = script(vec![Connection::NoContent]);
        assert_eq!(
            Vec::<String>::new(),
            data_of(sse(none, fast()).await).await.expect("ends")
        );
        assert_eq!(1, ids.lock().expect("ids").len());

        let (refused, _) = script(vec![
            Connection::Text("data: a\n\n"),
            Connection::Failure(missing),
        ]);
        let failure = data_of(sse(refused, fast()).await)
            .await
            .expect_err("a 404 is raised");
        assert_eq!(
            Some(404),
            api_error_of(failure.as_ref()).map(|e| e.status_code())
        );

        let (wrong, ids) = script(vec![
            Connection::Text("data: a\n\n"),
            Connection::Other(200, "text/html"),
        ]);
        let failure = data_of(sse(wrong, fast()).await)
            .await
            .expect_err("html is refused");
        assert!(failure.is::<SerializationError>());
        assert_eq!(
            2,
            ids.lock().expect("ids").len(),
            "asked once more, then refused the answer"
        );
    }

    #[tokio::test]
    async fn test_bhv_sse_016_an_sse_request_with_a_body_is_not_reconnected_unless_the_caller_turns_reconnect_on(
    ) {
        let (off, ids) = script(vec![
            Connection::Text("data: a\n\n"),
            Connection::Text("data: b\n\n"),
        ]);
        let stream = SseStream::open(
            off,
            text_decoder(),
            None,
            Some(&fast()),
            true,
            false,
            "POST",
            "/events",
        )
        .await
        .expect("opens");
        assert_eq!(vec!["a"], data_of(stream).await.expect("ends"));
        assert_eq!(1, ids.lock().expect("ids").len());

        let (on, _) = script(vec![
            Connection::Text("data: a\n\n"),
            Connection::Text("data: b\n\n"),
            Connection::NoContent,
        ]);
        let options = fast().max_reconnects(2);
        let stream = SseStream::open(
            on,
            text_decoder(),
            None,
            Some(&options),
            true,
            false,
            "POST",
            "/events",
        )
        .await
        .expect("opens");
        assert_eq!(vec!["a", "b"], data_of(stream).await.expect("ends"));

        let (single, ids) = script(vec![
            Connection::Text("data: a\n\n"),
            Connection::Text("data: b\n\n"),
            Connection::NoContent,
        ]);
        let options = fast().max_reconnects(2);
        let stream = SseStream::open(
            single,
            text_decoder(),
            None,
            Some(&options),
            true,
            true,
            "POST",
            "/events",
        )
        .await
        .expect("opens");
        assert_eq!(vec!["a"], data_of(stream).await.expect("ends"));
        assert_eq!(
            1,
            ids.lock().expect("ids").len(),
            "a single use body is never reconnected"
        );
    }

    #[tokio::test]
    async fn test_bhv_sse_017_an_sse_event_with_an_id_and_no_data_is_not_dispatched_but_updates_the_last_event_id_and_a_reconnect_resumes_from_it(
    ) {
        let (opener, ids) = script(vec![
            Connection::Text("data: a\nid: 1\n\nid: 2\n\n"),
            Connection::Text("data: b\nid: 3\n\n"),
            Connection::NoContent,
        ]);
        assert_eq!(
            vec!["a", "b"],
            data_of(sse(opener, fast()).await).await.expect("ends")
        );
        assert_eq!(
            vec!["".to_string(), "2".to_string()],
            ids.lock().expect("ids")[..2]
        );
    }

    #[tokio::test]
    async fn test_bhv_sse_021_the_configured_sse_terminator_ends_the_stream_and_is_not_delivered() {
        let (opener, _) = script(vec![Connection::Text(
            "data: a\n\ndata: [DONE]\n\ndata: b\n\n",
        )]);
        let stream = SseStream::open(
            opener,
            text_decoder(),
            Some("[DONE]".to_string()),
            Some(&fast()),
            false,
            false,
            "GET",
            "/events",
        )
        .await
        .expect("opens");
        assert_eq!(vec!["a"], data_of(stream).await.expect("ends"));
    }

    #[tokio::test]
    async fn test_bhv_sse_022_an_sse_event_named_error_raises_the_api_error_with_the_status_and_data_and_any_other_name_is_an_item(
    ) {
        let (opener, ids) = script(vec![
            Connection::Text(
                "event: update\ndata: fine\n\nevent: error\ndata: {\"why\":\"bad\"}\n\n",
            ),
            Connection::Text("data: again\n\n"),
        ]);
        let mut stream = sse(opener, fast()).await;
        assert_eq!(
            "update",
            stream.next().await.expect("event").expect("an item").event
        );
        let failure = stream
            .next()
            .await
            .expect("the failure")
            .expect_err("the error event");
        let api_error = failure.downcast_ref::<ApiError>().expect("an api error");
        assert_eq!(200, api_error.status_code());
        assert_eq!(Some("{\"why\":\"bad\"}"), api_error.response_body());
        assert_eq!(
            1,
            ids.lock().expect("ids").len(),
            "an error event is not reconnected"
        );
        assert!(stream.next().await.is_none());
    }
}
